#!/usr/bin/env python3
# eval cases for specs.jsonl. Run: python3 cases.py  -> cases.jsonl ; then python3 ../library_arch_nov20/lib_kb.py cases cases.jsonl specs.jsonl
import json
C = []; N = {}
def case(st, coll, q, where, must, chunks, lead=None, kind='rule', mustnot=None, level='pipelayer', strict=True):
    k = (st, coll); N[k] = N.get(k, 0) + 1
    d = dict(id=f'lib-{st}-{coll}-{N[k]}', cat='specs', q=q, where=where, level=level, kind=kind, must=must, lead=lead or must[:1], chunks=chunks)
    if mustnot: d['mustnot'] = mustnot
    if st != 'us' and strict: d['state_strict'] = True
    C.append(d)
S = 'spec'
# ---- state DOT books (question does not name the state; the job's location does)
case('wa', S, 'How soon can we run equipment over new storm pipe on a DOT job?', 'Tacoma, WA', [r'3 (ft|feet|foot)'], ['spec-wa-dot-trench-1'])
case('wa', S, 'What mandrel size and how long after backfill for the sewer deflection test?', 'Spokane, WA', [r'95 ?(%|percent)', r'30 days'], ['spec-wa-dot-sewertest-1'], lead=[r'95 ?(%|percent)'])
case('wa', S, 'What pressure do we test a new water main at on a state spec job?', 'Olympia, WA', [r'225 psi'], ['spec-wa-dot-water-1'], lead=[r'225|150 psi'])
case('wa', S, 'How far apart can cleanouts be on a side sewer?', 'Everett, WA', [r'100 (ft|feet)'], ['spec-wa-dot-structures-1'], kind='simple')
