case('tx', S, 'How far does the sewer have to be from the water line?', 'San Antonio, TX', [r'9 (ft|feet)'], ['spec-tx-tceq-separation-1'], mustnot=[r'\b10 (ft|feet) horizontal'], kind='simple')
