case('co', S, 'What compaction and lift for structure backfill on a CDOT job?', 'Pueblo, CO', [r'95 ?(%|percent)', r'6 (in|inch)'], ['spec-co-dot-backfill-1'], lead=[r'95 ?(%|percent)'])
case('co', S, 'What is the deflection limit on plastic storm pipe and when is it measured?', 'Greeley, CO', [r'5 ?(%|percent)', r'30 days'], ['spec-co-dot-pipe-1'], lead=[r'5 ?(%|percent)'])
