case('fl', S, 'What density does FDOT require on pipe backfill?', 'Tampa, FL', [r'not confirmed|Section 125|librar'], ['spec-fl-dot-edition-1'], lead=[r'not confirmed|Section 125|librar'])
case('fl', S, 'Which FDOT spec book is in force right now?', 'Orlando, FL', [r'2026-27|July 1, 2026'], ['spec-fl-dot-edition-1'], kind='simple')
case('in', S, 'How much plastic storm pipe gets mandrel tested on an INDOT job?', 'Fort Wayne, IN', [r'10 ?(%|percent)'], ['spec-in-dot-pipe-1'], kind='simple')
case('in', S, 'What is the INDOT deflection limit for plastic pipe?', 'Evansville, IN', [r'not confirmed|Section 715|librar'], ['spec-in-dot-pipe-1'], lead=[r'not confirmed|Section 715|librar'])
case('nd', S, 'What size mandrel and when for plastic pipe under the mainline?', 'Fargo, ND', [r'95 ?(%|percent)', r'30 days'], ['spec-nd-dot-pipe-1'], lead=[r'95 ?(%|percent)'])
