case('ut', S, 'Which spec book do city water and sewer jobs here usually use?', 'Provo, UT', [r'APWA'], ['spec-ut-dot-edition-1'], kind='simple')
case('or', S, 'How fast can the camera travel on the storm pipe video?', 'Salem, OR', [r'30 (ft|feet) per minute'], ['spec-or-dot-bore-1'], kind='simple')
