# ---- national standards and maker guides (asked from many states; no state_strict)
T = 'std'
case('us', T, 'What is the minimum slope for an 8 inch sewer?', 'Omaha, NE', [r'0\.40?'], ['std-tenstates-slope-1'], kind='simple')
